require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/commerce.php';require_once __DIR__.'/../lib/payment.php';header('Content-Type: application/json; charset=utf-8');if(($_SERVER['REQUEST_METHOD']??'')!=='POST')json_response(405,['success'=>false,'message'=>'Method not allowed.']);if(PAYMENT_WEBHOOK_SECRET==='')json_response(503,['success'=>false,'message'=>'Payment webhook is not configured.']);$raw=file_get_contents('php://input')?:'';$signature=(string)($_SERVER['HTTP_X_PAYMENT_SIGNATURE']??'');$expected=hash_hmac('sha256',$raw,PAYMENT_WEBHOOK_SECRET);if($signature===''||!hash_equals($expected,$signature))json_response(401,['success'=>false,'message'=>'Invalid webhook signature.']);$payload=json_decode($raw,true);if(!is_array($payload))json_response(400,['success'=>false,'message'=>'Invalid webhook payload.']);$provider=preg_replace('/[^a-z0-9_-]/','',strtolower((string)($payload['provider']??'generic')));$eventId=trim((string)($payload['event_id']??''));$type=trim((string)($payload['type']??''));$attemptId=trim((string)($payload['payment_attempt_id']??''));if($eventId===''||$attemptId===''||!in_array($type,['payment.succeeded','payment.failed'],true))json_response(422,['success'=>false,'message'=>'Webhook fields are incomplete.']);$db=get_db();$db->beginTransaction();try{$record=uuid_string();try{$db->prepare('INSERT INTO payment_webhook_events (id,provider,provider_event_id,event_type,payload_hash,processing_status,received_at) VALUES (:id,:provider,:event,:type,:hash,"processing",UTC_TIMESTAMP())')->execute(['id'=>$record,'provider'=>$provider,'event'=>$eventId,'type'=>$type,'hash'=>hash('sha256',$raw)]);}catch(PDOException $e){if((string)$e->getCode()==='23000'){$db->rollBack();json_response(200,['success'=>true,'message'=>'Webhook already processed.']);}throw $e;}$attempt=$db->prepare('SELECT * FROM payment_attempts WHERE id=:id FOR UPDATE');$attempt->execute(['id'=>$attemptId]);$attempt=$attempt->fetch();if(!$attempt)throw new RuntimeException('Payment attempt not found.');if(abs((float)$attempt['amount']-(float)($payload['amount']??$attempt['amount']))>0.001||strtoupper((string)($payload['currency']??'INR'))!==$attempt['currency'])throw new RuntimeException('Payment amount or currency does not match.');if($type==='payment.succeeded')confirm_online_order((int)$attempt['order_id'],trim((string)($payload['provider_payment_id']??$eventId)));else fail_online_order((int)$attempt['order_id'],trim((string)($payload['failure_message']??'Payment failed.')));$db->prepare('UPDATE payment_webhook_events SET processing_status="processed",processed_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$record]);audit_event('payment.webhook_processed','order',(string)$attempt['order_id'],['provider'=>$provider,'event_id'=>$eventId,'type'=>$type],['type'=>'system','id'=>'00000000-0000-0000-0000-000000000000']);$db->commit();json_response(200,['success'=>true]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
